// Mod 3: REWRITE. End a prompt with ?? and Claude is asked for a short, plain answer.
const NOTE = 'Answer in plain words for a beginner. Five sentences at most. No code unless asked.'

export function register(on) {
  on('prompt.submit', async ($, e, next) => {
    // An empty prompt is stopped here and never sent
    if (e.text.trim() === '') return { drop: 'Nothing to send.' }
    // A prompt without the mark goes on exactly as typed
    if (!e.text.trim().endsWith('??')) return next(e)
    // Pass on a changed copy: one ? instead of two, and one extra line for Claude
    const text = e.text.trim().slice(0, -1)
    return next({ ...e, text, context: [...(e.context ?? []), NOTE] })
  })
}

